script:
// Navigation only -- no permission/authorization logic. Whichever cards
// exist in this block's HTML are the same five for every user (see the
// block's own docstring in fixtures/custom_html_block.json); this script
// never decides which ones show. Real access control happens exactly
// where it already did before this block existed: Page.is_permitted()
// on the destination route.
root_element.querySelectorAll(".fg-home-card[data-route]").forEach(function (card) {
	card.addEventListener("click", function (event) {
		// Let a modified click (new tab / new window / middle click) fall
		// through to the real <a href> instead of intercepting it -- only
		// a plain left click gets the SPA route change.
		if (event.metaKey || event.ctrlKey || event.shiftKey || event.button === 1) {
			return;
		}
		event.preventDefault();
		frappe.set_route([card.dataset.route]);
	});
});

style:
.fg-home {
	--fg-home-bg: #f8fafc;
	--fg-home-card: #ffffff;
	--fg-home-border: #e5e9f0;
	--fg-home-text: #101828;
	--fg-home-text-muted: #667085;
	--fg-home-primary: #2b7be4;
	--fg-home-primary-tint: #eaf2fd;
	--fg-home-radius-lg: 18px;
	--fg-home-radius-md: 14px;
	--fg-home-shadow: 0 1px 2px rgba(16, 24, 40, 0.04), 0 4px 12px rgba(16, 24, 40, 0.05);
	--fg-home-shadow-hover: 0 4px 10px rgba(16, 24, 40, 0.06), 0 10px 24px rgba(16, 24, 40, 0.08);
	--fg-home-transition: 200ms ease;

	max-width: 1180px;
	margin: 0 auto;
	padding: 20px 20px 32px;
	background: var(--fg-home-bg);
	box-sizing: border-box;
}

.fg-home,
.fg-home * {
	box-sizing: border-box;
}

.fg-home-header {
	padding: 4px 4px 24px;
}

.fg-home-header h1 {
	margin: 0 0 4px;
	font-size: 1.5rem;
	font-weight: 700;
	color: var(--fg-home-text);
}

.fg-home-header p {
	margin: 0;
	font-size: 0.95rem;
	color: var(--fg-home-text-muted);
}

.fg-home-grid {
	display: grid;
	grid-template-columns: repeat(3, 1fr);
	gap: 20px;
}

.fg-home-card {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	min-height: 148px;
	padding: 24px;
	background: var(--fg-home-card);
	border: 1px solid var(--fg-home-border);
	border-radius: var(--fg-home-radius-lg);
	box-shadow: var(--fg-home-shadow);
	text-decoration: none;
	cursor: pointer;
	transition:
		transform var(--fg-home-transition),
		box-shadow var(--fg-home-transition),
		border-color var(--fg-home-transition);
}

.fg-home-card:hover,
.fg-home-card:focus-visible {
	transform: translateY(-2px);
	box-shadow: var(--fg-home-shadow-hover);
	border-color: var(--fg-home-primary);
}

.fg-home-card:focus-visible {
	outline: 2px solid var(--fg-home-primary);
	outline-offset: 2px;
}

.fg-home-icon {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 48px;
	height: 48px;
	border-radius: var(--fg-home-radius-md);
	background: var(--fg-home-primary-tint);
	margin-bottom: 12px;
	flex-shrink: 0;
}

.fg-home-icon-svg {
	width: 24px;
	height: 24px;
	fill: none;
	stroke: var(--fg-home-primary);
	stroke-width: 2;
	stroke-linecap: round;
	stroke-linejoin: round;
}

.fg-home-title {
	font-size: 1.05rem;
	font-weight: 600;
	color: var(--fg-home-text);
	margin-bottom: 4px;
}

.fg-home-subtitle {
	font-size: 0.85rem;
	color: var(--fg-home-text-muted);
	line-height: 1.35;
}

@media (max-width: 860px) {
	.fg-home-grid {
		grid-template-columns: repeat(2, 1fr);
	}
}

@media (max-width: 640px) {
	.fg-home {
		padding: 12px 12px 24px;
	}

	.fg-home-grid {
		grid-template-columns: 1fr;
		gap: 12px;
	}

	.fg-home-card {
		min-height: auto;
		padding: 18px;
	}
}
